def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def order_of_3_mod_197():
    m = 197
    phi = m - 1 # 196
    factors = prime_factorization(phi)

    possible_orders = []

    # Generate all divisors of 196
    divisors = set()
    for p, e in factors.items():
        current = 1
        for i in range(e + 1):
            divisors.add(current)
            current *= p

    # Now find the smallest divisor L such that 3^L = 1 (mod 197)
    L = phi
    for d in sorted(list(divisors)):
        if d < L:
            # Check if 3^d = 1 (mod 197)
            if pow(3, d, m) == 1:
                L = d

    return L

L = order_of_3_mod_197()
print(f"The order of 3 modulo 197 is: {L}")
print(f"The number of cycles is: {196 // L}")
